{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C25"],
      "claim": "Melperone, the closest analogue sharing the 4-fluorophenyl-butanoyl-piperidine core, has an absolute oral bioavailability of 67 ± 28.0% in healthy volunteers, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Haloperidol, a close butyrophenone antipsychotic with a 4-substituted piperidine, shows oral bioavailability of 44–74% in humans, supporting high oral bioavailability for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Bromperidol, the 4-bromophenyl analogue of haloperidol, has 30% oral bioavailability in humans, still above the 20% threshold and consistent with high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Ketanserin, a piperidine-containing 4-fluorophenyl ketone, has an absolute bioavailability of 45 ± 7% in hypertensive patients, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Mizolastine, a piperidine/benzimidazole-containing drug, has an absolute bioavailability of 69.3% in humans, providing additional support for high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Lumateperone, a more complex butyrophenone-related antipsychotic, has only 4.4% absolute oral bioavailability in humans, showing that some more distant analogues in the family can be low.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C31"],
      "claim": "A benzimidazole-piperidine analogue with a fluorobenzyl substituent has only 3% oral bioavailability in humans, a low outlier that is structurally more distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues, especially melperone, haloperidol, and bromperidol, consistently show human oral bioavailability above 20%, often 30–70%. The low-bioavailability outliers are structurally more distant and carry different metabolic/efflux liabilities. The physicochemical prior is uncertain and is outweighed by the transferable experimental evidence from close butyrophenone analogues, so the query is predicted to have F ≥ 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule (benperidol) is present in the evidence set.",
    "The low-bioavailability analogues are structurally more distant, so their relevance to the query is limited.",
    "No explicit data on first-pass metabolism, efflux transport, or formulation effects for the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

